/* ═══════════════════════════════════
   stamps.js — 소미쌤 도장 공유 데이터
   student.html / home.html 공통 사용
═══════════════════════════════════ */
const STAMPS={
  apple:    {svg:`<svg viewBox="0 0 80 80" xmlns="http://www.w3.org/2000/svg"><image href="data:image/png;base64," x="0" y="0" width="80" height="80"/></svg>`},
  sunflower:    {svg:`<svg viewBox="-10 8 100 100" xmlns="http://www.w3.org/2000/svg"><image href="data:image/png;base64," x="0" y="0" width="80" height="80"/></svg>`},
  cloud:    {svg:`<svg viewBox="0 0 80 80" xmlns="http://www.w3.org/2000/svg"><image href="data:image/png;base64," x="0" y="0" width="80" height="80"/></svg>`},
  crown:    {svg:`<svg viewBox="0 12 80 80" xmlns="http://www.w3.org/2000/svg"><image href="data:image/png;base64," x="0" y="0" width="80" height="80"/></svg>`},
  heart:    {svg:`<svg viewBox="0 0 80 80" xmlns="http://www.w3.org/2000/svg"><image href="data:image/png;base64," x="0" y="0" width="80" height="80"/></svg>`},
  rainbow:  {svg:`<svg viewBox="8 14 64 64" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M10 56 C10 34 22 18 40 18 C58 18 70 34 70 56" stroke="#e83030" stroke-width="3.5" stroke-linecap="round" fill="none"/><path d="M16 56 C16 37 27 24 40 24 C53 24 64 37 64 56" stroke="#f5a000" stroke-width="3.2" stroke-linecap="round" fill="none"/><path d="M22 56 C22 40 30 30 40 30 C50 30 58 40 58 56" stroke="#f5d800" stroke-width="3" stroke-linecap="round" fill="none"/><path d="M28 56 C28 43 33 36 40 36 C47 36 52 43 52 56" stroke="#30b030" stroke-width="3" stroke-linecap="round" fill="none"/><path d="M34 56 C34 46 37 42 40 42 C43 42 46 46 46 56" stroke="#3080e8" stroke-width="3" stroke-linecap="round" fill="none"/></svg>`},
};
function getStampSVG(key){
  const raw=(STAMPS[key]||STAMPS.apple).svg;
  // SVG 안에 base64 PNG가 박혀 있으면(<image href="data:image/png...">),
  // 일부 환경(https·Safari)에서 SVG 내부 image가 차단돼 빈 칸이 된다.
  // → 그 PNG를 꺼내 <img>로 직접 표시 (이미지 데이터는 그대로 재사용).
  const m=raw.match(/href="(data:image\/[^"]+)"/);
  if(m){
    return '<img src="'+m[1]+'" alt="" style="width:100%;height:100%;object-fit:contain;display:block;" draggable="false">';
  }
  // PNG가 없는 순수 벡터 SVG(예: rainbow)는 그대로 반환
  return raw;
}

/* 선생님 별표 도장 SVG */
const TEACHER_STAMPS={
  star:`<svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" style="transform:rotate(-15deg)" width="20" height="20"><path d="M12 2.5 C12.3 2.5 12.6 4.2 13.2 6.1 L14.5 10.2 L18.8 10.3 C20.1 10.3 20.8 10.8 20.3 11.5 L16.9 14.1 L18.3 18.2 C18.8 19.5 18.3 20.2 17.2 19.6 L12 16.8 L6.8 19.6 C5.7 20.2 5.2 19.5 5.7 18.2 L7.1 14.1 L3.7 11.5 C3.2 10.8 3.9 10.3 5.2 10.3 L9.5 10.2 L10.8 6.1 C11.4 4.2 11.7 2.5 12 2.5Z" stroke="#FFEE00" stroke-width="1.2" fill="#FFEE00"/></svg>`,
  heart:`<svg viewBox="0 0 80 80" xmlns="http://www.w3.org/2000/svg"><image href="data:image/png;base64," x="0" y="0" width="80" height="80"/></svg>`,
};
function getTeacherStampSVG(type, size){
  const svg = TEACHER_STAMPS[type]||TEACHER_STAMPS.star;
  // PNG가 박힌 도장(heart 등)은 <img>로 직접 표시 (https·Safari 호환)
  const m=svg.match(/href="(data:image\/[^"]+)"/);
  if(m){
    const px=size||20;
    return '<img src="'+m[1]+'" alt="" width="'+px+'" height="'+px+'" style="object-fit:contain;display:block;" draggable="false">';
  }
  // 순수 벡터(star)는 기존 방식대로 size 주입
  if(!size) return svg;
  let result = svg.replace(/(<svg[^>]*?)width="\d+" height="\d+"/, `$1width="${size}" height="${size}"`);
  if(result === svg) result = svg.replace('<svg ', `<svg width="${size}" height="${size}" `);
  return result;
}
